const esc = x => String(x ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const id = () => globalThis.crypto?.randomUUID?.() || `id-${Date.now()}-${Math.random().toString(36).slice(2)}`;
const num = x => x == null || String(x).trim() === '' ? null : (Number.isFinite(Number(x)) ? Number(x) : null);
/** Parse explicitly supplied frequency/value pairs without coercing missing cells to zero. */
export function parseSamplePairs(input, {maxSamples=5000}={}) {
  const source=String(input ?? '').trim();
  if(!source) throw new Error('Enter frequency and value pairs.');
  const rows=source.split(/\r?\n/);
  if(rows.length>maxSamples) throw new Error(`Enter no more than ${maxSamples} samples.`);
  const number='[+-]?(?:\\d+(?:\\.\\d*)?|\\.\\d+)(?:[eE][+-]?\\d+)?';
  const pair=new RegExp(`^(${number})(?:\\s*,\\s*|\\s+)(${number})$`);
  let previous=0;
  return rows.map(row=>{const match=row.trim().match(pair); if(!match) throw new Error('Use exactly one frequency and value per line.'); const frequency=Number(match[1]),value=Number(match[2]); if(!Number.isFinite(frequency)||frequency<=previous||frequency>3000||!Number.isFinite(value)) throw new Error('Use increasing positive frequencies up to 3000 MHz and finite values.'); previous=frequency; return [frequency,value];});
}
const fmt = x => x == null || !Number.isFinite(Number(x)) ? '—' : Number(x).toFixed(1);
const options = (items, selected) => items.map(([v,l]) => `<option value="${esc(v)}" ${String(v)===String(selected)?'selected':''}>${esc(l)}</option>`).join('');
const field = (label, name, value='', type='number', extra='') => `<label>${esc(label)}<input name="${esc(name)}" type="${type}" value="${esc(value)}" ${type==='number' && !extra.includes('step=')?'step="any"':''} ${extra}></label>`;
const physicalPortLabel = (node, port) => portLabel(node,port) + (portInfo(node).unverified.includes(port) ? ' (unverified)' : '');
const button = (text, action, cls='') => `<button type="button" class="${cls}" data-action="${action}">${text}</button>`;

export function removeStation(job,nodeId) {
  job.edges=job.edges.filter(e=>e.from!==nodeId && e.to!==nodeId);
  job.nodes=job.nodes.filter(n=>n.id!==nodeId);
  for(const key of Object.keys(job.portSweeps||{})) if(key.startsWith(`${nodeId}::`)) delete job.portSweeps[key];
  if(job.placements) delete job.placements[nodeId];
}
export function snapshotMapExport(job) {
  const snapshot=structuredClone(job);
  return {job:snapshot,evaluation:evaluateRoute(snapshot)};
}
export function assignEolCandidate(job,candidateId,targetId) {
  const candidate=job.nodes.find(n=>n.id===candidateId),target=job.nodes.find(n=>n.id===targetId);
  if(!candidate||candidate.kind!=='eol'||candidate.tag||candidate.map?.symbolKind!=='unknown-endpoint'||!(candidate.needsIdentity===true||candidate.evidence?.needsIdentity===true)) throw new Error('Choose an unidentified map end.');
  if(!target||target.kind!=='eol'||target.map||target.id===candidateId) throw new Error('Choose an unplaced end-of-line station.');
  if(Object.keys(candidate.readings||{}).length||Object.keys(job.portSweeps||{}).some(key=>key.startsWith(candidateId+'::'))) throw new Error('The unidentified end has readings or sweeps; preserve its measurements before matching.');
  target.map={...structuredClone(candidate.map),confirmed:false};target.needsIdentity=false;
  job.edges=job.edges.map(edge=>edge.from===candidateId||edge.to===candidateId?{...edge,from:edge.from===candidateId?targetId:edge.from,to:edge.to===candidateId?targetId:edge.to,confirmed:false}:edge).filter(edge=>edge.from!==edge.to);
  for(const node of job.nodes) if(node.evidence?.upstreamCandidates) node.evidence={...node.evidence,upstreamCandidates:node.evidence.upstreamCandidates.map(v=>v===candidateId?targetId:v)};
  removeStation(job,candidateId);return target;
}
export function bindMapSource(job,candidateId) {
  const source=job.nodes.find(n=>n.id==='node'),candidate=job.nodes.find(n=>n.id===candidateId);
  if(!source||!candidate||candidate.id==='node'||!candidate.map)throw new Error('Choose a map symbol to bind to the source.');
  source.map={...candidate.map,confirmed:false};source.tag=candidate.tag||'';
  job.edges=job.edges.map(edge=>edge.from===candidateId||edge.to===candidateId?{...edge,from:edge.from===candidateId?'node':edge.from,to:edge.to===candidateId?'node':edge.to,port:'',confirmed:false}:edge).filter(edge=>edge.from!==edge.to);
  for(const node of job.nodes) if(node.evidence?.upstreamCandidates) node.evidence={...node.evidence,upstreamCandidates:node.evidence.upstreamCandidates.map(v=>v===candidateId?'node':v)};
  removeStation(job,candidateId);return source;
}
export function applyMapDraft(job,draft,addCandidates,sourceCandidateId=null) {
  if(job.map?.sha256===draft.sha256) return false;
  for(const node of job.nodes) delete node.map;
  for(const edge of job.edges) if(edge.mapSourceHash) edge.confirmed=false;
  job.placements={};
  job.map={sha256:draft.sha256,pages:draft.pages.map(p=>({
    pageNumber:p.pageNumber,width:p.width,height:p.height,viewBox:p.viewBox,
    rotation:p.rotation,userUnit:p.userUnit,viewportTransform:p.viewportTransform,
    symbols:(p.symbols||[]).map(s=>({id:s.id,labelBounds:s.labelBounds,symbolBounds:s.symbolBounds,equipmentBounds:s.equipmentBounds,annotationId:s.annotationId}))
  }))};
  if(addCandidates) {
    const ids=new Map();
    for(const candidate of draft.nodes||[]) {
      const node={...candidate,id:id(),name:candidate.name||candidate.tag||'Map candidate',tag:candidate.tag||'',kind:candidate.kind||'passive',modelId:'',settings:{}};
      if(candidate.map) node.map={...candidate.map,confirmed:false};
      ids.set(candidate.id,node.id); job.nodes.push(node);
    }
    const importedIds=new Set(ids.values());
    for(const node of job.nodes) if(importedIds.has(node.id)&&node.evidence?.upstreamCandidates) node.evidence={...node.evidence,upstreamCandidates:node.evidence.upstreamCandidates.map(v=>ids.get(v)||v)};
    for(const edge of draft.edges||[]) if(ids.has(edge.from)&&ids.has(edge.to)) job.edges.push({...edge,id:id(),from:ids.get(edge.from),to:ids.get(edge.to),port:'',cableId:'',lengthFt:null,confirmed:false,mapSourceHash:draft.sha256});
    if(sourceCandidateId&&ids.has(sourceCandidateId)) bindMapSource(job,ids.get(sourceCandidateId));
  }
  return true;
}

